insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049303', '$t=2$.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000493031', '40000000-0000-4000-8000-000000049303', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000493032', '40000000-0000-4000-8000-000000049303', 'Escreva as coordenadas', '$x=t, y=1+t, z=t.$', 2), ('70000000-0000-4000-8000-000000493033', '40000000-0000-4000-8000-000000049303', 'Substitua no plano', '$t+(1+t)+t=7.$', 3), ('70000000-0000-4000-8000-000000493034', '40000000-0000-4000-8000-000000049303', 'Resolva', '$3t=6 \Rightarrow t=2.$', 4), ('70000000-0000-4000-8000-000000493035', '40000000-0000-4000-8000-000000049303', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
