insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000493481', '40000000-0000-4000-8000-000000049348', 'Comece identificando qual relação vetorial ou geométrica está sendo pedida; essa escolha vem antes da substituição numérica.', 1), ('60000000-0000-4000-8000-000000493482', '40000000-0000-4000-8000-000000049348', 'Os coeficientes do plano formam seu vetor normal.', 2), ('60000000-0000-4000-8000-000000493483', '40000000-0000-4000-8000-000000049348', 'Uma reta é perpendicular a um plano quando seu diretor é paralelo ao normal.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049348', 'A reta é perpendicular ao plano.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. Relações espaciais são determinadas pelas direções: vetores diretores descrevem retas e vetores normais descrevem planos. Comparar proporcionalidade e produto escalar permite decidir paralelismo e perpendicularidade sem depender de um desenho em perspectiva. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000493481', '40000000-0000-4000-8000-000000049348', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000493482', '40000000-0000-4000-8000-000000049348', 'Extraia o normal', '$n_{\pi}=(9,1,-1).$', 2), ('70000000-0000-4000-8000-000000493483', '40000000-0000-4000-8000-000000049348', 'Compare', '$d=n_{\pi}.$', 3), ('70000000-0000-4000-8000-000000493484', '40000000-0000-4000-8000-000000049348', 'Conclua', 'O diretor da reta tem a direção normal ao plano; portanto, a reta o corta perpendicularmente.', 4), ('70000000-0000-4000-8000-000000493485', '40000000-0000-4000-8000-000000049348', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000049349', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000235', 'multiple_choice', 'medium', 'published', 'Considere os planos $\pi_1:9x+y=2$ e $\pi_2:x-9y=3$. Como eles se relacionam? Para decidir, justifique o resultado usando as coordenadas correspondentes.') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
