insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000493491', '40000000-0000-4000-8000-000000049349', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000493492', '40000000-0000-4000-8000-000000049349', 'Liste os normais', '$n_1=(9,1,0), n_2=(1,-9,0).$', 2), ('70000000-0000-4000-8000-000000493493', '40000000-0000-4000-8000-000000049349', 'Calcule o produto', '$n_1 \cdot n_2=9-9=0.$', 3), ('70000000-0000-4000-8000-000000493494', '40000000-0000-4000-8000-000000049349', 'Conclua', 'Normais ortogonais determinam planos perpendiculares.', 4), ('70000000-0000-4000-8000-000000493495', '40000000-0000-4000-8000-000000049349', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000049350', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000235', 'multiple_choice', 'medium', 'published', 'Qual plano é paralelo a $9x+2y-z=4$? Para decidir, verifique a interpretação antes de selecionar a alternativa.') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
